@startuml

abstract class Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double)
}

class BasicContract implements Contract {
  + contractNumber : int
  + balance : double
}

abstract class Option implements Contract {
}

class Data extends Option {}

class SMS extends Option {}

class Minutes extends Option {}

class DoubleTransfer extends Option {}

@enduml

